if (k == 0 || points.empty()) {
    return {};
}
if (k > points.size()) {
    k = points.size();
}
std::vector<std::pair<float, std::size_t>> distIdx;
distIdx.reserve(points.size());
for (std::size_t i = 0; i < points.size(); ++i) {
    const auto& p = points[i];
    float dx = p.x - searchPoint.x;
    float dy = p.y - searchPoint.y;
    float dz = p.z - searchPoint.z;
    float d2 = dx * dx + dy * dy + dz * dz;
    distIdx.emplace_back(d2, i);
}
std::nth_element(distIdx.begin(),
                 distIdx.begin() + static_cast<std::ptrdiff_t>(k),
                 distIdx.end(),
                 [](const auto& a, const auto& b) { return a.first < b.first; });
distIdx.resize(k);
std::sort(distIdx.begin(),
          distIdx.end(),
          [](const auto& a, const auto& b) { return a.first < b.first; });
std::vector<std::size_t> result;
result.reserve(k);
for (const auto& p : distIdx) {
    result.push_back(p.second);
}
return result;

